function buildPayload(type:QRType,p:Record<string,string>):string {
  const enc=encodeURIComponent;
  switch(type){
    case 'website':case 'pdf':case 'app':case 'review':case 'social':return p.url||'https://example.com';
    case 'menu':return window.location.origin+'/#/menu/'+(p.slug||'preview-menu-123');
    case 'text':return p.text||'';
    case 'email':return `mailto:${p.email||''}?subject=${enc(p.subject||'')}&body=${enc(p.body||'')}`;
    case 'phone':return `tel:${p.phone||''}`;
    case 'sms':return `sms:${p.phone||''}?body=${enc(p.message||'')}`;
    case 'whatsapp':return `https://wa.me/${(p.phone||'').replace(/\D/g,'')}?text=${enc(p.message||'')}`;
    case 'wifi':return `WIFI:T:${p.encryption||'WPA'};S:${escWifi(p.ssid||'')};P:${escWifi(p.password||'')};;`;
    case 'vcard':{const fullName=[p.firstName,p.lastName].filter(Boolean).join(' ');return ['BEGIN:VCARD','VERSION:3.0',`N:${p.lastName||''};${p.firstName||''};;;`,`FN:${fullName}`,`TITLE:${p.title||''}`,`ORG:${p.organization||''}`,`TEL:${p.phone||''}`,`EMAIL:${p.email||''}`,`URL:${p.website||''}`,`ADR:;;${p.address||''};;;;`,'END:VCARD'].join('\r\n');}
    case 'event':return ['BEGIN:VCALENDAR','VERSION:2.0','BEGIN:VEVENT',`SUMMARY:${p.name||''}`,`DTSTART:${(p.start||'').replace(/[-:T]/g,'')}`,`DTEND:${(p.end||'').replace(/[-:T]/g,'')}`,`LOCATION:${p.location||''}`,`DESCRIPTION:${p.description||''}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');
    case 'location':return `geo:${p.latitude||'0'},${p.longitude||'0'}?q=${enc(p.label||'')}`;
    case 'upi':{const q=new URLSearchParams({pa:p.upiId||'',pn:p.payee||'',cu:'INR'});if(p.amount)q.set('am',p.amount);if(p.note)q.set('tn',p.note);return `upi://pay?${q.toString()}`;}
    case 'product':return [`Product: ${p.name||''}`,`Price: ${p.currency||'INR'} ${p.price||''}`,p.sku?`SKU: ${p.sku}`:'',p.url?`Product page: ${p.url}`:'' ].filter(Boolean).join('\r\n');
  }
}

function createQr(data:string,design:QRDesign,size=1200){
  return new QRCodeStyling({width:size,height:size,type:'svg',data,margin:design.margin??16,qrOptions:{errorCorrectionLevel:'H'},dotsOptions:{color:design.foreground,...(design.gradient?{gradient:{type:'linear',rotation:((design.gradientRotation??45)*Math.PI)/180,colorStops:[{offset:0,color:design.gradientStart||design.foreground},{offset:1,color:design.gradientEnd||design.cornerColor}]}}:{}),type:design.dots as 'square'|'dots'|'rounded'|'extra-rounded'|'classy'|'classy-rounded'},cornersSquareOptions:{color:design.cornerColor,type:design.corners as 'square'|'dot'|'extra-rounded'},cornersDotOptions:{color:design.cornerColor,type:'dot'},backgroundOptions:{color:design.background},image:design.logoUrl||undefined,imageOptions:{crossOrigin:'anonymous',margin:5,imageSize:design.logoSize||.22,hideBackgroundDots:true}});
}
function QrPreview({value,design,className=''}:{value:string;design:QRDesign;className?:string}){
  const ref=useRef<HTMLDivElement>(null);
  useEffect(()=>{if(!ref.current)return;ref.current.replaceChildren();const qr=createQr(value||'KinetiQR',design,230);qr.append(ref.current);return()=>{ref.current?.replaceChildren();};},[value,design]);
  return <div ref={ref} className={className}/>;
}
